<template>
 <view class="directory-page has-tabbar"><NativeStatusSpacer/><view class="directory-title"><button @tap="back">‹</button><text>成长小主人</text><view/></view>
  <view class="directory-paper"><view class="search-bar"><PrototypeIcon name="search" tone="muted" :size="30"/><input v-model="keyword" maxlength="64" placeholder="搜索姓名或学号" confirm-type="search" @confirm="search"/><button @tap="search">查询</button></view>
   <view class="directory-filters"><picker :range="gradeLabels" :value="gradeIndex" @change="chooseGrade"><view>{{gradeLabels[gradeIndex]}} ⌄</view></picker><picker :range="statusLabels" :value="statusIndex" @change="chooseStatus"><view>{{statusLabels[statusIndex]}} ⌄</view></picker><picker :range="classLabels" :value="classIndex" @change="chooseClass"><view>{{classLabels[classIndex]}} ⌄</view></picker></view>
   <view v-if="loading" class="directory-state">正在加载</view><view v-else-if="error" class="directory-state error"><text>{{error}}</text><button @tap="initialize">重试</button></view>
   <view v-for="child in rows" :key="child.studentId" class="directory-child" @tap="openChild(child.studentId)"><view class="child-avatar"><PrototypeIcon name="user" tone="green" :size="44"/></view><view class="child-copy"><view class="child-heading"><text>{{child.studentName}}</text><text class="child-status" :class="{inactive:child.status==='INACTIVE'}">{{child.status==='ACTIVE'?'在读':'已离校'}}</text></view><text class="child-sub">学号 {{child.studentNumber || '未设置'}}</text><text v-if="child.classNames" class="child-sub">{{child.gradeNames}} · {{child.classNames}}</text></view><text class="child-arrow">›</text></view>
   <view v-if="!loading&&!error&&!rows.length" class="directory-state">暂无符合条件的成长小主人</view><view v-if="loadingMore" class="directory-state">正在加载更多</view><view v-else-if="appendError" class="directory-state error"><text>{{appendError}}</text><button @tap="loadMore">重试</button></view><view v-else-if="rows.length&&!hasMore" class="directory-state">已加载全部</view>
  </view><AppTabBar :items="ORG_TABS" :active="0"/>
 </view>
</template>
<script setup lang="ts">
import {ref,computed} from 'vue';
import {onShow,onHide,onUnload,onReachBottom} from '@dcloudio/uni-app';
import NativeStatusSpacer from '@/components/NativeStatusSpacer.vue';
import PrototypeIcon from '@/components/PrototypeIcon.vue';
import AppTabBar from '@/components/AppTabBar.vue';
import {ORG_TABS} from '@/config/tabbar';
import {institutionDirectoryApi,type DirectoryChild,type DirectoryOptions,type DirectoryFilters} from '@/api/institution-directory';
import {request} from '@/api/http';
import {getMiniappCapabilities} from '@/api/capability';
import {getOrganizationSession} from '@/session/organization-session';
const rows=ref<DirectoryChild[]>([]),options=ref<DirectoryOptions>({grades:[],classes:[]}),keyword=ref(''),gradeId=ref(''),classId=ref(''),status=ref<'ALL'|'ACTIVE'|'INACTIVE'>('ACTIVE');
const page=ref(0),total=ref(0),hasMore=ref(false),loading=ref(false),loadingMore=ref(false),error=ref(''),appendError=ref('');
let visible=false,revision=0,token='',institutionId='',applied:DirectoryFilters|null=null;
const gradeLabels=computed(()=>['全部年级',...options.value.grades.map(g=>g.name)]),gradeIndex=computed(()=>Math.max(0,options.value.grades.findIndex(g=>g.id===gradeId.value)+1));
const availableClasses=computed(()=>options.value.classes.filter(c=>!gradeId.value||c.gradeId===gradeId.value));
const classLabels=computed(()=>['全部班级',...availableClasses.value.map(c=>c.name)]),classIndex=computed(()=>Math.max(0,availableClasses.value.findIndex(c=>c.id===classId.value)+1));
const statusValues=['ALL','ACTIVE','INACTIVE'] as const,statusLabels=['全部状态','在读','已离校'],statusIndex=computed(()=>statusValues.indexOf(status.value));
function selection(){return uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string;typeCode?:string}|undefined;}
function sameScope(){const s=selection();return !!token&&getOrganizationSession()?.accessToken===token&&s?.accessToken===token&&s.organizationId===institutionId&&['SCHOOL','TRAINING_INSTITUTION'].includes(s.typeCode||'');}
function current(n:number){return visible&&n===revision&&sameScope();}
function reset(){rows.value=[];page.value=0;total.value=0;hasMore.value=false;appendError.value='';loadingMore.value=false;}
async function initialize(){visible=true;const n=++revision;const nextToken=getOrganizationSession()?.accessToken||'',nextId=selection()?.organizationId||'';if(token!==nextToken||institutionId!==nextId){keyword.value='';gradeId.value='';classId.value='';status.value='ACTIVE';}token=nextToken;institutionId=nextId;reset();options.value={grades:[],classes:[]};loading.value=true;error.value='';try{if(!sameScope())throw Error('请先选择学校或培训机构');const [me,cap]=await Promise.all([request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${token}`}}),getMiniappCapabilities()]);if(!current(n))return;if(!me.permissionCodes.includes('STUDENT_READ')||cap.classManagementEnabled!==true)throw Error('当前账号没有学员查看权限或功能未启用');const result=await institutionDirectoryApi.options(token,institutionId);if(!current(n))return;options.value=result;if(!result.grades.some(g=>g.id===gradeId.value))gradeId.value='';if(!result.classes.some(c=>c.id===classId.value))classId.value='';applied={institutionOrganizationId:institutionId,keyword:keyword.value.trim(),gradeOrganizationId:gradeId.value,classOrganizationId:classId.value,status:status.value};await fetchPage(1,n,applied);}catch(e){if(n===revision&&visible)error.value=e instanceof Error?e.message:'加载失败';}finally{if(n===revision)loading.value=false;}}
async function fetchPage(next:number,n:number,filters:DirectoryFilters){const result=await institutionDirectoryApi.list(token,filters,next);if(!current(n))return;const seen=new Set(next===1?[]:rows.value.map(r=>r.studentId));const added=result.items.filter(r=>!seen.has(r.studentId)&&!!seen.add(r.studentId));rows.value=next===1?added:[...rows.value,...added];page.value=result.page;total.value=result.total;hasMore.value=added.length>0&&result.page*(result.pageSize||20)<result.total;}
async function search(){if(!sameScope()||!visible)return;const n=++revision;reset();error.value='';loading.value=true;applied={institutionOrganizationId:institutionId,keyword:keyword.value.trim(),gradeOrganizationId:gradeId.value,classOrganizationId:classId.value,status:status.value};try{await fetchPage(1,n,applied);}catch(e){if(current(n))error.value=e instanceof Error?e.message:'查询失败';}finally{if(n===revision)loading.value=false;}}
async function loadMore(){if(!visible||!sameScope()||loading.value||loadingMore.value||!hasMore.value||!applied)return;const n=revision,snapshot={...applied};loadingMore.value=true;appendError.value='';try{await fetchPage(page.value+1,n,snapshot);}catch(e){if(current(n))appendError.value=e instanceof Error?e.message:'加载失败';}finally{if(n===revision)loadingMore.value=false;}}
function chooseGrade(e:{detail:{value:string}}){gradeId.value=options.value.grades[Number(e.detail.value)-1]?.id||'';classId.value='';void search();}
function chooseClass(e:{detail:{value:string}}){classId.value=availableClasses.value[Number(e.detail.value)-1]?.id||'';void search();}
function chooseStatus(e:{detail:{value:string}}){status.value=statusValues[Number(e.detail.value)]||'ALL';void search();}
function openChild(id:string){if(sameScope()&&rows.value.some(r=>r.studentId===id))uni.navigateTo({url:`/pages/institution-student-detail/institution-student-detail?studentId=${encodeURIComponent(id)}`});}
function back(){uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/organization-home/organization-home'})});}
function hide(){visible=false;++revision;reset();options.value={grades:[],classes:[]};applied=null;loading.value=false;error.value='';}
onShow(initialize);onHide(hide);onUnload(hide);onReachBottom(()=>{if(!appendError.value)void loadMore();});
</script>
<style scoped>
.directory-page{min-height:100vh;background:#17684f;color:#183c30;box-sizing:border-box;}.directory-title{height:86rpx;display:flex;align-items:center;justify-content:space-between;padding:0 24rpx;color:white;font-size:32rpx;font-weight:650;}.directory-title button{padding:0;margin:0;width:48rpx;background:transparent;color:white;font-size:48rpx;line-height:72rpx;}.directory-title>view{width:48rpx;}button::after{border:0;}.directory-paper{background:#fbfdfb;border-radius:30rpx 30rpx 0 0;padding:26rpx;min-height:calc(100vh - 180rpx);box-sizing:border-box;}.search-bar{display:flex;align-items:center;gap:12rpx;padding:10rpx 18rpx;background:#eef3f0;border-radius:26rpx;}.search-bar input{flex:1;min-width:0;font-size:26rpx;height:60rpx;}.search-bar button{margin:0;padding:0 10rpx;background:transparent;color:#17684f;font-size:24rpx;line-height:60rpx;}.directory-filters{display:flex;gap:12rpx;margin:20rpx 0;}.directory-filters picker{flex:1;min-width:0;}.directory-filters picker view{padding:14rpx 10rpx;background:#edf4ef;border-radius:14rpx;font-size:24rpx;text-align:center;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}.directory-child{display:flex;align-items:center;gap:20rpx;padding:24rpx 4rpx;border-bottom:1rpx solid #e7eee8;}.child-avatar{width:80rpx;height:80rpx;border-radius:50%;background:#e9f3e9;display:flex;align-items:center;justify-content:center;flex-shrink:0;}.child-copy{flex:1;min-width:0;}.child-heading{display:flex;align-items:center;flex-wrap:wrap;gap:14rpx;font-size:29rpx;font-weight:650;}.child-status{font-size:21rpx;font-weight:400;background:#e3f5e9;color:#258151;padding:4rpx 12rpx;border-radius:8rpx;}.child-status.inactive{background:#f0f1ee;color:#8a968c;}.child-sub{display:block;font-size:23rpx;color:#819087;line-height:1.6;overflow-wrap:anywhere;margin-top:6rpx;}.child-arrow{font-size:38rpx;color:#809489;}.directory-state{display:flex;flex-direction:column;align-items:center;gap:12rpx;padding:30rpx;color:#8a988e;font-size:24rpx;}.directory-state button{background:#edf4ed;color:#17684f;font-size:24rpx;}.error{color:#b45e46;}
</style>
